import itertools, random

def girth_at_least(edges, n, min_girth):
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    for s in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        q = [s]
        while q:
            u = q.pop(0)
            for w in adj[u]:
                if w == parent[u]:
                    continue
                if dist[w] == -1:
                    dist[w] = dist[u]+1
                    parent[w] = u
                    q.append(w)
                else:
                    length = dist[u] + dist[w] + 1
                    if length < min_girth:
                        return False
    return True

def chromatic_num(edges, n, max_colors):
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    colors = [-1]*n
    order = sorted(range(n), key=lambda x: len(adj[x]), reverse=True)
    def backtrack(idx):
        if idx == n:
            return True
        v = order[idx]
        used = [False]*max_colors
        for nb in adj[v]:
            if colors[nb] != -1:
                used[colors[nb]] = True
        for c in range(max_colors):
            if not used[c]:
                colors[v] = c
                if backtrack(idx+1):
                    return True
                colors[v] = -1
        return False
    if backtrack(0):
        return True, colors
    return False, None

n = 19
