for attempt in range(20000):
    vertices = list(range(n))
    random.shuffle(vertices)
    edges = [(vertices[i], vertices[(i+1)%n]) for i in range(n)]

    possible = [(i,j) for i in range(n) for j in range(i+1,n) if (i,j) not in edges and (j,i) not in edges]
    random.shuffle(possible)

    for e in possible:
        test = edges + [e]
        if girth_at_least(test, n, min_girth):
            edges = test

